"use client";

import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { useCart } from "@/context/CartContext";
import { formatVND, productImageUrl } from "@/lib/utils";
import { Minus, Plus, Trash2 } from "lucide-react";
import Image from "next/image";

interface CartItemProps {
  item: {
    id: number;
    name: string;
    price: number;
    image: string;
    quantity: number;
    stock?: number;
  };
  isLast: boolean;
}

export default function CartItem({ item, isLast }: CartItemProps) {
  const { removeFromCart, updateQuantity } = useCart();
  const stock = item.stock ?? 100;
  const isAtMaxStock = item.quantity >= stock;

  return (
    <div>
      <div className="flex items-start gap-4">
        <div className="relative h-[100px] w-[100px]">
          <Image
            src={productImageUrl(item.image)}
            alt={item.name}
            fill
            sizes="100px"
            className="rounded-lg bg-muted object-cover"
          />
        </div>

        <div className="min-w-0 flex-1">
          <div className="flex items-start justify-between">
            <div className="min-w-0 flex-1 pr-4">
              <h2 className="line-clamp-2 font-semibold text-foreground">
                {item.name}
              </h2>
              <p className="mt-1 text-sm text-muted-foreground">
                {formatVND(item.price)} mỗi sản phẩm
              </p>
              {isAtMaxStock && (
                <p className="mt-1 text-xs text-orange-600">
                  Đã đạt số lượng tối đa có thể mua
                </p>
              )}
            </div>

            <Button
              variant="ghost"
              size="icon"
              onClick={() => removeFromCart(item.id)}
              className="h-8 w-8 shrink-0 text-muted-foreground hover:text-destructive"
            >
              <Trash2 className="h-4 w-4" />
            </Button>
          </div>

          <div className="mt-4 flex items-center justify-between">
            <div className="flex items-center rounded-lg border border-border">
              <Button
                variant="ghost"
                size="icon"
                onClick={() => updateQuantity(item.id, Math.max(1, item.quantity - 1))}
                disabled={item.quantity <= 1}
                className="h-8 w-8 rounded-r-none"
              >
                <Minus className="h-3 w-3" />
              </Button>
              <span className="min-w-[50px] px-4 py-2 text-center text-sm font-medium">
                {item.quantity}
              </span>
              <Button
                variant="ghost"
                size="icon"
                onClick={() => updateQuantity(item.id, Math.min(stock, item.quantity + 1))}
                disabled={isAtMaxStock}
                className="h-8 w-8 rounded-l-none"
              >
                <Plus className="h-3 w-3" />
              </Button>
            </div>

            <div className="text-right">
              <p className="text-lg font-bold text-foreground">
                {formatVND(item.price * item.quantity)}
              </p>
            </div>
          </div>
        </div>
      </div>

      {!isLast && <Separator className="mt-4" />}
    </div>
  );
}
